"""Launch the official Crush binary with a native Codelaboon provider configuration."""
import hashlib
import json
import os
from pathlib import Path
import shlex
import subprocess
import socket
import time
import uuid
import tempfile

from codelaboon.paths import config_dir


def configuration(rows, default, profile='coding'):
    lines = [
        '# Generated by Codelaboon; native preferences/state live in the profile data directory.',
        'option default-providers false', 'option provider-auto-update false', 'option metrics false',
        "provider add codelaboon --name Codelaboon --type completions "
        "--base-url '$CODELABOON_GATEWAY_URL' --api-key '$CODELABOON_GATEWAY_TOKEN'",
    ]
    for row in rows:
        if row['api'] != 'chat':
            continue
        lines.append('model add ' + shlex.quote('codelaboon/' + row['id']) + ' --name ' + shlex.quote(row['name']) +
                     ' --context-window ' + ('8192' if row['id'].startswith('local/') else '32768') +
                     ' --default-max-tokens 4096 --thinking never --price-input 0 --price-output 0')
    for slot in ('large', 'small'):
        lines.append('model ' + slot + ' ' + shlex.quote('codelaboon/' + default) + ' --max-tokens 4096')
    if profile == 'security':
        lines.append('option global-context-path ' + shlex.quote(str(Path(__file__).parent / 'prompts/security.md')))
    return '\n'.join(lines) + '\n'


def launch(binary, arguments, profile, local_only, rows, url, token):
    root = Path(os.environ.get('CODELABOON_NATIVE_DIR') or config_dir()) / 'crush'
    project = Path.cwd().resolve()
    identity = hashlib.sha256(str(project).encode()).hexdigest()[:16]
    project_data=root/'projects'/identity
    project_data.mkdir(parents=True,exist_ok=True)
    (project_data/'.codelaboon-project.json').write_text(json.dumps({'cwd':str(project)}))
    default = os.environ.get('CODELABOON_TASK_CHAT_MODEL') or os.environ.get('CODELABOON_TASK_MODEL') or (rows[0]['id'] if local_only else 'free')
    env = dict(os.environ, CODELABOON_GATEWAY_URL=url, CODELABOON_GATEWAY_TOKEN=token,
               CRUSH_GLOBAL_DATA=str(root / 'global'), CRUSH_DATA_DIR=str(root / 'projects' / identity),
               CRUSH_CACHE_DIR=str(root / 'cache'), CRUSH_DISABLE_METRICS='true',
               CRUSH_DISABLE_DEFAULT_PROVIDERS='true', CRUSH_DISABLE_PROVIDER_AUTO_UPDATE='true',
               CRUSH_CLIENT_SERVER='false')
    # Each concurrent launch has its own provider metadata; only native state persists.
    with tempfile.TemporaryDirectory(prefix='codelaboon-crush-', dir='/tmp' if os.name != 'nt' else None) as directory:
        (Path(directory) / 'crushrc').write_text(configuration(rows, default, profile), encoding='utf-8')
        env['CRUSH_GLOBAL_CONFIG'] = directory
        if arguments[:1] in (["run"], ("run",), ["r"], ("r",)):
            return run_with_server(binary, arguments, project, env, directory)
        from codelaboon.execution_policy import full_access
        return subprocess.call([binary, *(['-y','-y'] if full_access() else []), *arguments], cwd=project, env=env)


def server_ready(address):
    """Probe only the private per-launch IPC endpoint, never a public TCP port."""
    request = b'GET /v1/health HTTP/1.1\r\nHost: localhost\r\nConnection: close\r\n\r\n'
    try:
        if os.name == 'nt':
            import ctypes
            if not ctypes.windll.kernel32.WaitNamedPipeW(address, 100):
                return False
            with open(address, 'r+b', buffering=0) as pipe:
                pipe.write(request)
                return b' 200 ' in pipe.read(128)
        with socket.socket(socket.AF_UNIX) as connection:
            connection.settimeout(0.2)
            connection.connect(address)
            connection.sendall(request)
            return b' 200 ' in connection.recv(128)
    except OSError:
        return False


def run_with_server(binary, arguments, project, env, temporary):
    # Crush's native client/server run path drains final messages reliably. The
    # local run path can lose fast completions. Own this server's entire lifetime.
    address = (r'\\.\pipe\codelaboon-crush-' + uuid.uuid4().hex if os.name == 'nt'
               else str(Path(temporary) / 'server.sock'))
    host = ('npipe:////./pipe/' + address.rsplit('\\', 1)[-1] if os.name == 'nt' else 'unix://' + address)
    options = dict(env, CRUSH_CLIENT_SERVER='true', CRUSH_SERVER_READY_TIMEOUT='15s',
                   CRUSH_CACHE_DIR=str(Path(temporary) / 'cache'))
    from codelaboon.execution_policy import full_access
    flags=['-y','-y'] if full_access() else []
    with (Path(temporary) / 'server.log').open('w+') as log:
        server = subprocess.Popen([binary, *flags, 'server', '--host', host], cwd=project, env=options,
                                  stdin=subprocess.DEVNULL, stdout=log, stderr=log)
        try:
            deadline = time.monotonic() + 15
            while not server_ready(address):
                if server.poll() is not None or time.monotonic() > deadline:
                    log.seek(0)
                    raise RuntimeError('Crush server did not become ready: ' + log.read()[-2000:])
                time.sleep(0.05)
            return subprocess.call([binary, *flags, '--host', host, *arguments], cwd=project, env=options)
        finally:
            if server.poll() is None:
                server.terminate()
                try:
                    server.wait(timeout=5)
                except subprocess.TimeoutExpired:
                    server.kill()
                    server.wait()
